#!/bin/bash
set -e
mkdir -p /logs/verifier

# Stop the original fixed-answer server so the submitted client can be tested
# against fresh, verifier-generated expressions on the required port.
pkill -f '^python3 /home/user/ws_server.py' 2>/dev/null || true
sleep 1

cat << 'TEST_EOF' > /tmp/test_final_state.py
import ast
import asyncio
import json
import math
import os
import re
import secrets
import sys
from fractions import Fraction

import websockets


def test_result_file_exists_and_correct():
    """Verify that the result file was generated by the mock server and contains the correct token."""
    result_file = "/home/user/result.txt"
    assert os.path.isfile(result_file), "The file /home/user/result.txt does not exist. Did the script run successfully?"

    with open(result_file, "r") as f:
        content = f.read().strip()

    assert content == "SUCCESS_84729_SECURE_EVAL", f"The content of /home/user/result.txt is incorrect. Found: {content}"


def test_python_script_secure():
    """Verify that the Python script exists and does not use unsafe dynamic execution."""
    script_file = "/home/user/fetch_limits.py"
    assert os.path.isfile(script_file), "The Python script /home/user/fetch_limits.py does not exist."

    with open(script_file, "r") as f:
        content = f.read()

    # Preserve the original security assertions.
    assert not re.search(r'\beval\s*\(', content), "The script contains 'eval(', which is forbidden by the security constraint."
    assert not re.search(r'\bexec\s*\(', content), "The script contains 'exec(', which is forbidden by the security constraint."

    tree = ast.parse(content, filename=script_file)
    forbidden = {"eval", "exec", "compile"}
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
            assert node.id not in forbidden, f"The script accesses unsafe dynamic execution function {node.id!r}."
        if isinstance(node, ast.Attribute):
            assert node.attr not in forbidden, f"The script accesses unsafe dynamic execution attribute {node.attr!r}."
        if isinstance(node, ast.ImportFrom) and node.module == "builtins":
            for alias in node.names:
                assert alias.name not in forbidden, f"The script imports unsafe built-in {alias.name!r}."
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "getattr" and len(node.args) >= 2:
            name_arg = node.args[1]
            if isinstance(name_arg, ast.Constant) and isinstance(name_arg.value, str):
                assert name_arg.value not in forbidden, f"The script obtains unsafe function {name_arg.value!r} via getattr."
        if isinstance(node, ast.Subscript):
            key = node.slice
            if isinstance(key, ast.Constant) and isinstance(key.value, str):
                assert key.value not in forbidden, f"The script obtains unsafe function {key.value!r} by subscription."


def test_client_protocol_and_dynamic_evaluation():
    """Run the submitted client against unpredictable arithmetic expressions."""
    async def exercise_client():
        rand = lambda low, high: low + secrets.randbelow(high - low + 1)
        values = [rand(2, 60) for _ in range(21)]
        (a, b, c, d, e, f, g, h, i, j, k, l, m, n, p, q, r, s, t, u, v) = values

        expressions = [
            f"{a} + {b} * ({c} - {d})",
            f"({e} + {f}) / {g}",
            f"{h} - ({i} * {j}) + ({k} / {l})",
            f"(({m} + {n}) * ({p} - {q})) / {r}",
            f"{s} / ({t} + {u}) - {v}",
        ]
        expected = [
            Fraction(a) + Fraction(b) * (Fraction(c) - Fraction(d)),
            (Fraction(e) + Fraction(f)) / Fraction(g),
            Fraction(h) - Fraction(i) * Fraction(j) + Fraction(k, l),
            ((Fraction(m) + Fraction(n)) * (Fraction(p) - Fraction(q))) / Fraction(r),
            Fraction(s, t + u) - Fraction(v),
        ]

        completed = asyncio.Event()
        errors = []

        async def handler(websocket, *args):
            try:
                await websocket.send(json.dumps(expressions))
                raw_response = await asyncio.wait_for(websocket.recv(), timeout=8)
                response = json.loads(raw_response)
                assert isinstance(response, list), "Client response must be a JSON list."
                assert len(response) == len(expected), "Client returned the wrong number of results."
                for index, (actual, wanted) in enumerate(zip(response, expected)):
                    assert isinstance(actual, (int, float)) and not isinstance(actual, bool), \
                        f"Result {index} is not numerical: {actual!r}"
                    assert math.isfinite(float(actual)), f"Result {index} is not finite."
                    assert math.isclose(float(actual), float(wanted), rel_tol=1e-10, abs_tol=1e-10), \
                        f"Incorrect result for {expressions[index]!r}: got {actual!r}, expected {float(wanted)!r}"
            except BaseException as exc:
                errors.append(exc)
            finally:
                completed.set()

        proc = None
        async with websockets.serve(handler, "localhost", 9999):
            proc = await asyncio.create_subprocess_exec(
                sys.executable,
                "/home/user/fetch_limits.py",
                cwd="/home/user",
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            try:
                await asyncio.wait_for(completed.wait(), timeout=10)
                stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=5)
            except BaseException:
                if proc.returncode is None:
                    proc.kill()
                    await proc.communicate()
                raise

        assert not errors, f"WebSocket protocol/evaluation failed: {errors[0]}"
        assert proc.returncode == 0, (
            f"Client exited with status {proc.returncode}.\n"
            f"stdout: {stdout.decode(errors='replace')}\n"
            f"stderr: {stderr.decode(errors='replace')}"
        )

    asyncio.run(exercise_client())
TEST_EOF

if python3 -m pytest --noconftest -c /dev/null -p no:cacheprovider /tmp/test_final_state.py -x --tb=short 2>&1; then
    echo "1" > /logs/verifier/reward.txt
else
    echo "0" > /logs/verifier/reward.txt
fi
